from __future__ import annotations

import re
from bisect import bisect_right
from datetime import date, datetime, timedelta

_MONTH_NAMES = {
    name: number
    for number, name in enumerate(
        ("JAN", "FEB", "MAR", "APR", "MAY", "JUN",
         "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"),
        start=1,
    )
}
_WEEKDAY_NAMES = {
    name: number
    for number, name in enumerate(
        ("SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT")
    )
}

_UINT = re.compile(r"[0-9]+\Z")


def _parse_value(text: str, low: int, high: int, names: dict[str, int] | None) -> int:
    """Parse one literal value or symbolic name in a field."""
    if names is not None:
        named = names.get(text.upper())
        if named is not None:
            return named
    if not _UINT.match(text):
        raise ValueError(f"invalid cron value: {text!r}")
    value = int(text)
    if not low <= value <= high:
        raise ValueError(
            f"cron value {value} outside range {low}-{high}"
        )
    return value


def _parse_item(
    item: str, low: int, high: int, names: dict[str, int] | None
) -> range:
    """Expand one comma-separated item into the values it denotes."""
    if not item:
        raise ValueError("empty cron item")

    pieces = item.split("/")
    if len(pieces) > 2:
        raise ValueError(f"invalid cron item: {item!r}")
    base = pieces[0]

    step = 1
    if len(pieces) == 2:
        step_text = pieces[1]
        if not _UINT.match(step_text):
            raise ValueError(f"invalid cron step: {item!r}")
        step = int(step_text)
        if step < 1:
            raise ValueError(f"cron step must be at least 1: {item!r}")

    if base == "*":
        start, end = low, high
    elif "-" in base:
        bounds = base.split("-")
        if len(bounds) != 2 or not bounds[0] or not bounds[1]:
            raise ValueError(f"invalid cron range: {item!r}")
        start = _parse_value(bounds[0], low, high, names)
        end = _parse_value(bounds[1], low, high, names)
        if start > end:
            raise ValueError(f"reversed cron range: {item!r}")
    else:
        start = _parse_value(base, low, high, names)
        if len(pieces) == 1:
            return range(start, start + 1)
        end = high

    return range(start, end + 1, step)


def _parse_field(
    text: str,
    low: int,
    high: int,
    names: dict[str, int] | None = None,
    normalize=None,
) -> frozenset[int]:
    """Expand a whole field into its set of values."""
    values: set[int] = set()
    for item in text.split(","):
        values.update(_parse_item(item, low, high, names))
    if normalize is not None:
        values = {normalize(value) for value in values}
    return frozenset(values)


def _add_years(moment: datetime, years: int) -> datetime:
    """Add calendar years, clamping Feb 29 to Feb 28 if needed."""
    try:
        return moment.replace(year=moment.year + years)
    except ValueError:
        return moment.replace(year=moment.year + years, day=28)


def _cron_weekday(day: date) -> int:
    """Python's Monday-first weekday as cron's Sunday-first number."""
    return (day.weekday() + 1) % 7


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(
            f"cron expression must have exactly five fields: {expression!r}"
        )
    minute_text, hour_text, dom_text, month_text, dow_text = fields

    minutes = _parse_field(minute_text, 0, 59)
    hours = _parse_field(hour_text, 0, 23)
    days_of_month = _parse_field(dom_text, 1, 31)
    months = _parse_field(month_text, 1, 12, _MONTH_NAMES)
    days_of_week = _parse_field(
        dow_text, 0, 7, _WEEKDAY_NAMES, normalize=lambda value: value % 7
    )

    at_least_one_time = sorted(
        hour * 60 + minute for hour in hours for minute in minutes
    )

    # Vixie cron: two restricted day fields are alternatives, not requirements.
    dom_restricted = dom_text != "*"
    dow_restricted = dow_text != "*"
    either_day = dom_restricted and dow_restricted

    def day_matches(day: date) -> bool:
        dom_ok = day.day in days_of_month
        dow_ok = _cron_weekday(day) in days_of_week
        return (dom_ok or dow_ok) if either_day else (dom_ok and dow_ok)

    start = after.date()
    # The search window ends five calendar years after ``after`` (inclusive),
    # so leap days are accounted for without assuming 365-day years.
    end = _add_years(after, 5)
    end_date = end.date()
    start_minute = after.hour * 60 + after.minute

    current = start
    while current <= end_date:
        if current.month in months and day_matches(current):
            # On the first day, only times strictly later than the minute
            # containing ``after`` can be strictly after ``after`` itself.
            cutoff = start_minute if current == start else -1
            index = bisect_right(at_least_one_time, cutoff)
            if index < len(at_least_one_time):
                minute_of_day = at_least_one_time[index]
                candidate = datetime(
                    current.year,
                    current.month,
                    current.day,
                    minute_of_day // 60,
                    minute_of_day % 60,
                )
                if candidate <= end:
                    return candidate
        current += timedelta(days=1)

    raise ValueError(
        f"no run of {expression!r} within five years after {after.isoformat()}"
    )
